require("dotenv").config();
const fs = require("node:fs");
const pool = require("./config/db");

(async () => {
  try {
    if (process.env.DB_NAME !== "defaultdb") {
      throw new Error("Configured database is not defaultdb.");
    }
    const [[selected]] = await pool.query("SELECT DATABASE() AS database_name");
    if (!selected || selected.database_name !== "defaultdb") {
      throw new Error("Connected database is not defaultdb.");
    }
    console.log("Connected database confirmed: defaultdb");

    const sql = fs.readFileSync("../database/schema_e_seed.sql", "utf8");
    const statements = sql.split(/;\s*(?:\r?\n|$)/).map((part) => part.trim()).filter(Boolean);
    for (const statement of statements) {
      await pool.query(statement);
    }
    console.log(`Schema and seed applied (${statements.length} statements).`);

    const [columns] = await pool.query("SHOW COLUMNS FROM perguntas");
    const columnNames = columns.map((column) => column.Field);
    const requiredColumns = ["id", "etapa_escolar", "nivel_estrutural", "enunciado", "opcao_a", "opcao_b", "opcao_c", "opcao_d", "resposta_correta", "explicacao", "tags"];
    if (requiredColumns.some((name) => !columnNames.includes(name))) {
      throw new Error("perguntas structure does not match the required columns.");
    }
    console.log(`perguntas structure confirmed (${columnNames.length} columns).`);

    const [counts] = await pool.query(
      "SELECT etapa_escolar, nivel_estrutural, COUNT(*) AS question_count FROM perguntas GROUP BY etapa_escolar, nivel_estrutural"
    );
    const stages = ["Fundamental", "Médio", "Superior"];
    const combinations = [];
    for (const stage of stages) {
      for (let level = 1; level <= 3; level += 1) {
        const row = counts.find((item) => item.etapa_escolar === stage && Number(item.nivel_estrutural) === level);
        if (!row || Number(row.question_count) < 1) {
          throw new Error(`Missing question for ${stage}, level ${level}.`);
        }
        combinations.push(`${stage}/${level}: ${row.question_count}`);
      }
    }
    console.log(`All 9 stage/level combinations have questions: ${combinations.join("; ")}`);

    const { createQuestionRepository, toPublicQuestion } = require("./repositories/questionRepository");
    const repository = createQuestionRepository(pool);
    const result = await repository.findRandomQuestion({ etapaEscolar: "Médio", nivelEstrutural: 2 });
    if (!result) throw new Error("The repository returned no row for a valid filter.");
    const publicQuestion = toPublicQuestion(result);
    const publicKeys = Object.keys(publicQuestion);
    if (publicKeys.includes("resposta_correta") || publicKeys.includes("explicacao")) {
      throw new Error("Public question contains a restricted field.");
    }
    console.log(`Real repository query succeeded; public fields: ${publicKeys.join(", ")}; answer/explanation excluded.`);
  } catch (error) {
    const code = error && error.code ? ` (${error.code})` : "";
    const message = String(error && error.message ? error.message : "Unknown database error")
      .replace(/(?:password|passwd|pwd|user|host|database)\s*[:=]\s*[^\s,;]+/gi, "$1=[redacted]")
      .replace(/mysql(?:s)?:\/\/[^\s]+/gi, "[redacted connection URI]");
    console.error(`Database validation failed${code}: ${message}`);
    process.exitCode = 1;
  } finally {
    await pool.end();
  }
})();
